<script setup lang="ts">
import{computed,onMounted,onUnmounted,ref,watch}from'vue';import Icon from'./Icon.vue';import PlaylistBatchCard from'./PlaylistBatchCard.vue';import{api}from'./api';import{t,errorText}from'./i18n';import{cleanName,type Task}from'../../../packages/contracts';import{type PlaylistBatchView,type PlaylistSummary,type PlaylistEntry}from'../../../packages/playlists/contracts';
const props=defineProps<{tabId:number;pageUrl:string;tasks:Task[];folder:string;saveAs:boolean;revision?:string}>();const data=ref<PlaylistSummary>(),entries=ref<PlaylistEntry[]>([]),selected=ref(new Set<string>()),autoSelect=ref(true),quality=ref<0|480|720|1080>(0),loading=ref(false),starting=ref(false),error=ref(''),job=ref<PlaylistBatchView&{quality:number;updatedAt:number;keys?:string[]}>(),page=ref(1);let disposed=false,timer:ReturnType<typeof setInterval>,reading=false,polling=false;
const available=computed(()=>entries.value.filter(e=>e.available)),locked=computed(()=>!!job.value&&!['completed','cancelled'].includes(job.value.state)),count=computed(()=>available.value.filter(e=>selected.value.has(e.key)).length),pageCount=computed(()=>Math.max(1,Math.ceil(entries.value.length/50))),visible=computed(()=>entries.value.slice((page.value-1)*50,page.value*50));
const folder=computed(()=>job.value?.destination?`${job.value.destination.folder}/${job.value.destination.subfolder}`:`${props.folder}/${cleanName(data.value?.title??'YouTube')}`),view=computed(()=>job.value);
function toggle(key:string,value:boolean){const next=new Set(selected.value);if(value)next.add(key);else next.delete(key);selected.value=next;}
function all(value:boolean){autoSelect.value=value;selected.value=value?new Set(available.value.map(e=>e.key)):new Set();}
async function status(){if(polling||disposed)return;polling=true;try{const next=await api<PlaylistBatchView&{quality:0|480|720|1080;updatedAt:number;keys?:string[];unchanged?:boolean}|undefined>('youtubePlaylistStatus',{compact:true,id:job.value?.id,tabId:props.tabId,pageUrl:props.pageUrl,since:job.value?.updatedAt});if(next&&!next.unchanged){const first=!job.value;job.value=next;if(first&&!['completed','cancelled'].includes(next.state)){selected.value=new Set(next.keys??[]);quality.value=next.quality;}}}catch{/* The catalogue and retry actions remain available. */}finally{polling=false;}}
async function load(){if(reading||disposed)return;reading=true;loading.value=true;error.value='';try{
 const initial=await api<PlaylistSummary&{entries:PlaylistEntry[]}>('youtubePlaylistGet',{tabId:props.tabId});if(disposed)return;const previous=data.value?.revision;data.value=initial;entries.value=initial.entries;if(previous!==initial.revision){all(true);page.value=1;}
 await status();while(!disposed&&data.value&&!data.value.complete){const next=await api<PlaylistSummary&{entries:PlaylistEntry[]}>('youtubePlaylistGet',{tabId:props.tabId,more:true,after:entries.value.length});if(disposed)return;if(next.revision!==data.value.revision)throw new Error('playlistRead');const keys=new Set(entries.value.map(e=>e.key));const extra=next.entries.filter(e=>!keys.has(e.key));entries.value.push(...extra);const selection=new Set(selected.value);for(const e of extra)if(e.available&&autoSelect.value&&!locked.value)selection.add(e.key);selected.value=selection;data.value=next;}
 }catch(e){error.value=errorText((e as Error).message);}finally{reading=false;loading.value=false;}}
async function start(){if(starting.value||!data.value?.complete||!count.value)return;starting.value=true;error.value='';try{const id=await api<string>('youtubePlaylistStart',{tabId:props.tabId,revision:data.value.revision,keys:available.value.filter(e=>selected.value.has(e.key)).map(e=>e.key),quality:quality.value});job.value=await api('youtubePlaylistStatus',{id,compact:true});}catch(e){error.value=errorText((e as Error).message);}finally{starting.value=false;}}
watch(()=>props.revision,(value,old)=>{if(value&&value!==old&&value!==data.value?.revision)void load();});
onMounted(()=>{void load();timer=setInterval(()=>{void status();},1000);});onUnmounted(()=>{disposed=true;clearInterval(timer);});
</script>
<template>
 <section class="youtube-playlist" :aria-label="t('playlistTitle')">
  <header class="playlist-heading"><span class="playlist-symbol"><Icon name="library" /></span><div><p class="eyebrow">{{ t('playlistTitle') }}</p><h2 dir="auto" :title="data?.title">{{ data?.title || t('playlistLoading') }}</h2><p>{{ t('playlistSelection',[String(count),String(entries.length)]) }}<span v-if="loading"> · {{ t('playlistLoading') }}</span></p></div></header>
  <p v-if="data?.snapshot" class="playlist-hint playlist-snapshot">{{ t('playlistSnapshot') }}</p>
  <p v-if="error" class="task-error" role="alert">{{ error }} <button class="text-button" :disabled="loading" @click="load"><Icon name="refresh" />{{ t('scan') }}</button></p>
  <PlaylistBatchCard v-if="view" :job="view" :tasks="tasks" compact @changed="status" />
  <template v-if="entries.length && !locked">
   <div class="playlist-selection"><label><input type="checkbox" :checked="count === available.length && !!count" :indeterminate="count > 0 && count < available.length" :disabled="locked || !available.length" @change="all(($event.target as HTMLInputElement).checked)">{{ t('playlistSelectAll') }}</label><button class="text-button" :disabled="locked || !count" @click="all(false)">{{ t('clearSelection') }}</button></div>
   <div class="playlist-entries">
    <label v-for="entry in visible" :key="entry.key" class="playlist-entry" :class="{unavailable:!entry.available}"><input type="checkbox" :checked="selected.has(entry.key)" :disabled="locked || !entry.available" :aria-label="entry.title || t('playlistUnavailable')" @change="toggle(entry.key,($event.target as HTMLInputElement).checked)"><bdi class="playlist-index">{{ entry.index+1 }}</bdi><span dir="auto" :title="entry.title">{{ entry.title || t('playlistUnavailable') }}</span><Icon v-if="!entry.available" name="shield" :title="t('playlistUnavailable')" /></label>
   </div>
   <nav v-if="pageCount > 1" class="playlist-pagination" :aria-label="t('playlistTitle')"><button class="text-button" :disabled="page <= 1" @click="page--">{{ t('previousPage') }}</button><span>{{ t('pageStatus',[String(page),String(pageCount)]) }}</span><button class="text-button" :disabled="page >= pageCount" @click="page++">{{ t('nextPage') }}</button></nav>
   <div class="playlist-quality"><label>{{ t('quality') }}<select v-model.number="quality" :disabled="locked"><option :value="0">{{ t('playlistBest') }}</option><option :value="1080">1080p</option><option :value="720">720p</option><option :value="480">480p</option></select></label><button v-if="!locked" class="primary" :disabled="loading || starting || !data?.complete || !count" @click="start"><Icon name="download" />{{ t('playlistDownload',[String(count)]) }}</button></div>
   <p class="playlist-folder"><Icon name="folder" /><span>{{ t('playlistFolder') }} <bdi>{{ folder }}</bdi><small v-if="saveAs"> · {{ t('saveAsk') }}</small></span></p>
  </template>
  <p v-else-if="!locked && !loading && !error" class="task-notice">{{ t('playlistEmpty') }}</p>
  <p class="playlist-hint">{{ t('playlistHint') }}</p>
 </section>
</template>
